-- SafetyTraining v20.065
-- Worker general training evidence enrichment. Creates draft v3 from existing general-v2 content.

with base as (
 select lu.id learning_unit_id,lu.stable_key,v.content
 from public.learning_units lu
 join public.learning_unit_versions v on v.learning_unit_id=lu.id and v.version_number=2
 where lu.stable_key in ('generale:rischio','generale:prevenzione-protezione','generale:organizzazione','generale:diritti-doveri','generale:incidenti','generale:emergenze-generale','generale:segnaletica-generale')
), enriched as (
 select learning_unit_id,stable_key,
 content || jsonb_build_object(
   'didactic_version','general-evidence-v3',
   'quality',coalesce(content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true),
   'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','normative_validation','D.Lgs. 81/2008 vigente + ASR 17/04/2025','reuse_policy','reference_and_original_rewrite'),
   'evidence_sources',jsonb_build_array(
      jsonb_build_object('authority','Ministero del Lavoro e delle Politiche Sociali','title','Accordo Stato-Regioni 17 aprile 2025','url','https://lavoro.gov.it/temi-e-priorita/salute-e-sicurezza/focus/pagine/accordo-stato-regioni-del-17042025-materia-di-formazione','use','normative_validation','checked_on','2026-10-15'),
      jsonb_build_object('authority','Normattiva','title','D.Lgs. 81/2008 - testo vigente','url','https://www.normattiva.it/eli/id/2008/04/30/008G0104/CONSOLIDATED','use','normative_validation','checked_on','2026-10-15'),
      jsonb_build_object('authority','Regione Emilia-Romagna','title','Materiali didattici per la formazione delle figure della prevenzione','url','https://salute.regione.emilia-romagna.it/sicurezza-nei-luoghi-di-lavoro/formazione/materiali-didattici','use','method_and_structure_reference','checked_on','2026-10-15')
   ) || case when stable_key='generale:incidenti' then jsonb_build_array(jsonb_build_object('authority','INAIL','title','Condivido - sviluppo delle conoscenze sui near miss','url','https://www.inail.it/portale/it/inail-comunica/pubblicazioni/catalogo-generale/catalogo-generale-dettaglio.2025.04.condivido-approccio-integrato-in-reti-collaborative-sviluppo-conoscenze-near-miss.html','use','near_miss_method_reference','checked_on','2026-10-15')) when stable_key='generale:emergenze-generale' then jsonb_build_array(jsonb_build_object('authority','Corpo Nazionale dei Vigili del Fuoco','title','Materiale didattico per corsi antincendio','url','https://www.vigilfuoco.it/comando-vvf-napoli/formazione-le-aziende/materiale-didattico-i-corsi-di-formazione-8108','use','emergency_method_reference','checked_on','2026-10-15')) else '[]'::jsonb end,
   'source_integration_note','Contenuti, casi e schemi restano originali SafetyTraining. Le fonti esterne sono usate per validazione normativa, metodo e casi/evidenze, senza copia diretta.'
 ) || case stable_key
   when 'generale:rischio' then jsonb_build_object('risk_chain_lab',jsonb_build_object('title','Dal pericolo al danno: dove puoi interrompere la catena?','chain',jsonb_build_array('pericolo/sorgente','condizione di esposizione','evento o contatto','conseguenza/danno','barriere già presenti','barriera più efficace da aggiungere'),'scenarios',jsonb_build_array('pavimento bagnato in passaggio','organo meccanico accessibile','prodotto irritante usato senza aspirazione adeguata','movimentazione con visibilità ridotta','carico di lavoro che induce scorciatoie'),'task','Per ogni scenario distinguere il pericolo dalla probabilità di esposizione e dal danno possibile; poi indicare in quale punto della catena una misura può impedire l’evento.','teacher_debrief','Il rischio non coincide con il pericolo: cambia quando cambiano esposizione, modalità di lavoro e barriere.'),'dynamic_risk_rule','Se cambiano attività, ambiente, persone, attrezzature o barriere, cambia anche la valutazione operativa della situazione: fermarsi e chiedere verifica quando la configurazione reale non è quella prevista.')
   when 'generale:prevenzione-protezione' then jsonb_build_object('hierarchy_lab',jsonb_build_object('title','Prima elimina o riduci il rischio, poi proteggi ciò che resta','levels',jsonb_build_array('eliminazione del pericolo','sostituzione/riduzione alla fonte','misure tecniche/collettive','misure organizzative/procedurali','informazione/formazione/addestramento','DPI per il rischio residuo quando necessari'),'exercise','Dati quattro scenari, ordinare le misure dalla più strutturale alla più debole e spiegare perché mettere un cartello o usare più attenzione non può sostituire una barriera tecnica disponibile.','output_required','Per ogni caso: misura primaria, misura complementare, rischio residuo e come verificare che la misura funzioni.'),'effectiveness_check',jsonb_build_array('la misura esiste realmente?','è utilizzabile nel lavoro reale?','le persone sanno come applicarla?','resta efficace nel tempo?','esiste una condizione di stop se manca?'))
   when 'generale:organizzazione' then jsonb_build_object('who_to_call_lab',jsonb_build_object('title','Chi coinvolgo e perché?','actors',jsonb_build_array('datore di lavoro','dirigente','preposto','RSPP/ASPP','medico competente','RLS','addetti emergenza/primo soccorso','lavoratore'),'situations',jsonb_build_array('procedura non applicabile','DPI danneggiato o inadatto','macchina con protezione inefficace','malessere collegato a possibile esposizione','interferenza con appaltatore','pericolo immediato durante il lavoro','misura del DVR non attuata'),'task','Associare a ogni situazione il primo interlocutore operativo e gli eventuali soggetti da coinvolgere, evitando di confondere ruoli tecnici, rappresentativi e gerarchici.'),'escalation_pattern',jsonb_build_array('riconosci il problema','metti in sicurezza/stop se necessario','informa il referente appropriato','fornisci fatti osservabili','attendi o richiedi la correzione','riprendi solo quando la condizione è gestita'))
   when 'generale:diritti-doveri' then jsonb_build_object('worker_action_cards',jsonb_build_object('title','Che cosa faccio se vedo una condizione non sicura?','cards',jsonb_build_array(jsonb_build_object('situation','pericolo grave o immediato','action','non esporsi, interrompere/abbandonare secondo la situazione e le procedure applicabili, avvisare immediatamente i soggetti competenti'),jsonb_build_object('situation','difetto/anomalia senza pericolo immediato','action','non improvvisare riparazioni non di competenza; segnalare con fatti e impedire usi non sicuri se previsto'),jsonb_build_object('situation','istruzione non compresa o incompatibile con il lavoro reale','action','chiedere chiarimento prima di eseguire; non colmare il vuoto con una scorciatoia'),jsonb_build_object('situation','DPI/presidio non disponibile o non utilizzabile','action','segnalare e non sostituire il presidio con una soluzione improvvisata')),'report_template',jsonb_build_array('fatto osservato','luogo/fase','rischio evidente o conseguenza plausibile','misura/presidio mancante o inefficace','azione immediata adottata','referente informato')),'participation_rule','Il lavoratore contribuisce alla prevenzione anche segnalando anomalie e partecipando a formazione/addestramento; questo non trasferisce su di lui gli obblighi organizzativi dei soggetti che dispongono di poteri e risorse.')
   when 'generale:incidenti' then jsonb_build_object('near_miss_micro_lab',jsonb_build_object('title','È andata bene: quindi che cosa abbiamo imparato?','sequence',jsonb_build_array('descrivi i fatti','ricostruisci la sequenza','individua cosa avrebbe potuto succedere','identifica barriere assenti/inefficaci/bypassate','cerca fattori tecnici/organizzativi/procedurali','segnala e contribuisci alle informazioni utili','verifica che il problema non si ripeta'),'scenario','Un carico passa vicino a un lavoratore senza colpirlo: nessun danno, ma la separazione mezzi-pedoni non è rispettata. Il corsista deve spiegare perché non archiviare l’evento come nulla di successo.','anti_blame_rule','Raccogliere fatti e barriere prima di attribuire colpe; il near miss serve a prevenire il prossimo evento.'),'reporting_value','Una segnalazione utile descrive ciò che è avvenuto e le condizioni che lo hanno reso possibile, non soltanto il risultato finale.')
   when 'generale:emergenze-generale' then jsonb_build_object('emergency_decision_lab',jsonb_build_object('title','Allarme: prima riconosci il tuo ruolo, poi agisci','sequence',jsonb_build_array('riconosci il segnale/evento','interrompi in sicurezza se possibile','segui istruzioni e vie previste','non assumere compiti per cui non sei addestrato','non rientrare o cambiare percorso per recuperare beni','raggiungi il punto/condizione prevista e segnala informazioni utili','attendi indicazioni per rientro o ripresa'),'scenarios',jsonb_build_array('allarme incendio','collega che si sente male','odore/fumo anomalo','sversamento o perdita','via di esodo temporaneamente non disponibile'),'task','Per ogni scenario distinguere azione del lavoratore, azione degli addetti designati e situazione che richiede soccorsi/gestione tecnica.'),'drill_learning_rule','Una prova di emergenza serve anche a scoprire criticità di allarme, percorsi, ruoli e comunicazione: anomalie osservate vanno segnalate e corrette.')
   when 'generale:segnaletica-generale' then jsonb_build_object('sign_to_action_lab',jsonb_build_object('title','Il cartello comunica una regola: quale comportamento richiede?','families',jsonb_build_array('divieto','avvertimento/pericolo','obbligo','salvataggio/soccorso','antincendio'),'task','Mostrare segnaletica inserita in scenari realistici e chiedere: che cosa comunica, quale azione richiede, quale rischio/barriera sottostante deve comunque essere presente, che cosa fai se il segnale è incoerente con la situazione reale?','anti_substitution_rule','La segnaletica informa e orienta; non sostituisce una protezione tecnica, una segregazione o un’organizzazione necessaria quando il rischio richiede quelle misure.'),'scenario','Un cartello di divieto accesso è presente ma la barriera fisica è rimossa e l’area pericolosa è facilmente raggiungibile: il corsista deve riconoscere che il segnale da solo non rende l’area sicura.')
   end as new_content
 from base
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,3,'draft',new_content,md5(new_content::text),null from enriched
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'mlps-asr-2025','normative_validation','Fonte ufficiale MLPS dell’ASR 2025 per formazione generale dei lavoratori.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key like 'generale:%'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'normattiva-dlgs81-vigente','normative_validation','Validazione vigente di concetti, obblighi, diritti, ruoli e organizzazione della prevenzione.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key like 'generale:%'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'rer-formazione-figure-prevenzione','method_reference','Riferimento metodologico per rischio, prevenzione/protezione, organizzazione, emergenze e segnaletica, con adattamento originale SafetyTraining.',date '2026-10-15',jsonb_build_object('reuse_policy','adapt_with_attribution_where_applicable') from public.learning_units lu where lu.stable_key like 'generale:%'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'inail-condivido-near-miss','near_miss_method_reference','Metodo INAIL per imparare da near miss ed eventi sentinella senza fermarsi all’assenza di danno.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key='generale:incidenti'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
insert into public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
select lu.id,'vvf-materiali-antincendio','emergency_method_reference','Riferimento tecnico-didattico VVF per logica di allarme, esodo e comportamenti in emergenza.',date '2026-10-15','{}'::jsonb from public.learning_units lu where lu.stable_key='generale:emergenze-generale'
on conflict (learning_unit_id,source_key,purpose) do update set relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
